// Search the entire incoming item for a string containing both "Title" and "PDF Text"
function findText(obj) {
  if (typeof obj === "string" && obj.includes("Title") && obj.includes("PDF Text")) return obj;
  if (typeof obj === "object" && obj !== null) {
    for (const key in obj) {
      const found = findText(obj[key]);
      if (found) return found;
    }
  }
  return null;
}

const textData = findText($json);

if (!textData) {
  return [{
    json: {
      error: "No combined text found in input",
      title: "",
      pdfText: ""
    }
  }];
}

// Replace escaped newlines (\n) with real ones
const fixed = textData.replace(/\r/g, "").replace(/\\n/g, "\n");

// Extract title and pdf text
const titleMatch = fixed.match(/Title\s*:\s*(.*?)\n\s*PDF\s*Text\s*:/s);
const pdfMatch = fixed.match(/PDF\s*Text\s*:\s*([\s\S]*)/s);

const title = titleMatch ? titleMatch[1].trim() : "";
const pdfText = pdfMatch ? pdfMatch[1].trim() : "";

// Output clean data
return [{
  json: {
    title,
    pdfText
  }
}];

const item = items[0].json;

