const cleanMarkdown = (line) => 
    line
      .replace(/\*\*(.*?)\*\*/g, '$1')   // remove **bold**
      .replace(/##\s*/g, '')             // remove headings ##
      .replace(/\*/g, '');               // remove single *

// === Text wrapping ===
const wrapText = (text, width = 90) => {
    const lines = [];
    for (const rawLine of text.split(/\r?\n/)) {
        let line = '';
        for (const word of rawLine.split(' ')) {
            if ((line + word).length > width && line.length > 0) {
                lines.push(line.trim());
                line = word + ' ';
            } else {
                line += word + ' ';
            }
        }
        if (line.trim()) lines.push(line.trim());
        else lines.push('');
    }
    return lines;
};

// === Page layout settings ===
const pageWidth = 595.28;
const pageHeight = 841.89;
const left = 72;
const top = 800;
const bottom = 60;
const lineHeight = 14;

// === PDF page build ===
let pages = [];
let y = top;

// === Start first page ===
let current = `BT /F2 20 Tf ${left} ${top} Td (${safe(title)}) Tj ET\nBT\n`;
y -= 30;

// === Process each line ===
const allLines = text.split(/\r?\n/);

for (let i = 0; i < allLines.length; i++) {
    let rawLine = allLines[i];
    const isQuestion = /^\s*(\*\*|\d+\.)/.test(rawLine.trim());
    const boldFont = isQuestion ? '/F2 12 Tf' : '/F1 12 Tf';
    const cleaned = cleanMarkdown(rawLine);
    const wrappedLines = wrapText(cleaned);

    for (const line of wrappedLines) {
        if (y < bottom) {
            current += "ET";
            pages.push(current);
            current = `BT\n`;
            y = top;
        }

        y -= lineHeight;

        if (line.trim()) {
            current += `${boldFont}\n1 0 0 1 ${left} ${y} Tm (${safe(line)}) Tj\n`;
        } else {
            y -= lineHeight / 2;
        }
    }
}

current += "ET";
pages.push(current);

// === Build final PDF ===
let pdf = "%PDF-1.4\n";
const offsets = [];

const addObject = (content) => {
    offsets.push(pdf.length);
    pdf += content + "\n";
};

addObject(`1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj`);
const kids = pages.map((_, i) => `${3 + i * 2} 0 R`).join(' ');
addObject(`2 0 obj << /Type /Pages /Count ${pages.length} /Kids [${kids}] >> endobj`);

const fontObjectIndex = 3 + pages.length * 2;
const boldFontObjectIndex = fontObjectIndex + 1;

let objectIndex = 3;
for (const pageStream of pages) {
    addObject(`${objectIndex} 0 obj << /Type /Page /Parent 2 0 R /MediaBox [0 0 ${pageWidth} ${pageHeight}] /Resources << /Font << /F1 ${fontObjectIndex} 0 R /F2 ${boldFontObjectIndex} 0 R >> >> /Contents ${objectIndex + 1} 0 R >> endobj`);
    objectIndex++;
    addObject(`${objectIndex} 0 obj << /Length ${pageStream.length} >> stream\n${pageStream}\nendstream endobj`);
    objectIndex++;
}

addObject(`${fontObjectIndex} 0 obj << /Type /Font /Subtype /Type1 /BaseFont /Helvetica >> endobj`);
addObject(`${boldFontObjectIndex} 0 obj << /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >> endobj`);

const xref_offset = pdf.length;
pdf += "xref\n";
pdf += `0 ${offsets.length + 1}\n`;
pdf += "0000000000 65535 f \n";
offsets.forEach(offset => {
    pdf += `${offset.toString().padStart(10, '0')} 00000 n \n`;
});

pdf += "trailer\n";
pdf += `<< /Root 1 0 R /Size ${offsets.length + 1} >>\n`;
pdf += "startxref\n";
pdf += `${xref_offset}\n`;
pdf += "%%EOF";

return [{
    binary: {
        data: {
            data: Buffer.from(pdf).toString('base64'),
            mimeType: 'application/pdf',
            fileName: `${title}.pdf`,
        },
    },
}];

/**
 * n8n Input Processor (JSON + Filename-Aware)
 * Handles text-only, URL, and filename-based input even without binary.
 * Version 3: Added .txt and .doc/.docx detection
 */

// --- 1️⃣ Init ---
let output = {
  inputType: "unknown",
  binaryType: "none",
  rawText: null,
  rawUrl: null,
  hasBinary: false,
  mimeType: null,
  fileName: null,
};

// --- 2️⃣ Safe Access ---
const binaryData = typeof $binary !== 'undefined' && $binary ? $binary : {};
const jsonData = typeof $json !== 'undefined' && $json ? $json : {};

// --- 3️⃣ Detect Binary ---
const binaryKeys = Object.keys(binaryData);
let file = null;
if (binaryKeys.length > 0) {
  const firstKey = binaryKeys[0];
  file = binaryData[firstKey];
  output.hasBinary = true;
  output.fileName = file.fileName || null;
  output.mimeType = file.mimeType || "application/octet-stream";
}

// --- 4️⃣ Extract Text + URL ---
const textInput = (
  jsonData.text ||
  jsonData.question ||
  jsonData.message ||
  jsonData.prompt ||
  jsonData.content ||
  (jsonData.body && jsonData.body.text) ||
  (jsonData.body && jsonData.body.question) ||
  (jsonData.body && jsonData.body.message) ||
  (jsonData.body && jsonData.body.prompt) ||
  (jsonData.body && jsonData.body.content) ||
  ""
).toString().trim();

const urlInput = (
  jsonData.url ||
  (jsonData.body && jsonData.body.url) ||
  ""
).toString().trim();


// --- 5️⃣ Helper ---
function isUrl(str) {
  if (!str) return false;
  return /^https?:\/\/[^\s]+$/i.test(str);
}

// --- 6️⃣ Try Detecting File Mentions in Text ---
const filePattern = /([a-zA-Z0-9_-]+\.(pdf|jpg|jpeg|png|mp4|txt|doc|docx))/i;
const fileMatch = textInput.match(filePattern);
if (fileMatch) {
  output.fileName = fileMatch[1];
}

// --- 7️⃣ Determine Input Type ---
if (output.hasBinary && file) {
  output.inputType = "file_only";

  // --- Detect MIME / File Type ---
  if (output.mimeType.startsWith("application/pdf")) {
    output.binaryType = "pdf";
  } else if (output.mimeType.startsWith("image/")) {
    output.binaryType = "image";
  } else if (output.mimeType.startsWith("video/")) {
    output.binaryType = "video";
  } else if (
    output.mimeType === "text/plain" ||
    (output.fileName && output.fileName.endsWith(".txt"))
  ) {
    output.binaryType = "txt";
  } else if (
    output.mimeType === "application/msword" ||
    output.mimeType === "application/vnd.openxmlformats-officedocument.wordprocessingml.document" ||
    (output.fileName && /\.(doc|docx)$/i.test(output.fileName))
  ) {
    output.binaryType = "doc";
  } else {
    output.binaryType = "other_file";
  }

  if (textInput) {
    output.inputType = `${output.binaryType}_with_text`;
    output.rawText = textInput;
  }

} else if (isUrl(urlInput)) {
  output.inputType = "url_only";
  output.rawUrl = urlInput;

} else if (isUrl(textInput)) {
  output.inputType = "url_only";
  output.rawUrl = textInput;

} else if (fileMatch && textInput) {
  output.inputType = "text_with_filename";
  output.rawText = textInput;

} else if (textInput) {
  output.inputType = "text_only";
  output.rawText = textInput;

} else {
  output.inputType = "unknown";
}

// --- 8️⃣ Return ---
return [
  {
    json: output,
    binary: file ? { data: file } : {},
  },
];

