    output.binaryType = "txt";
  } else if (
    output.mimeType === "application/msword" ||
    output.mimeType === "application/vnd.openxmlformats-officedocument.wordprocessingml.document" ||
    (output.fileName && /\.(doc|docx)$/i.test(output.fileName))
  ) {
    output.binaryType = "doc";
  } else {
    output.binaryType = "other_file";
  }

  if (textInput) {
    output.inputType = `${output.binaryType}_with_text`;
    output.rawText = textInput;
  }

} else if (isUrl(urlInput)) {
  output.inputType = "url_only";
  output.rawUrl = urlInput;

} else if (isUrl(textInput)) {
  output.inputType = "url_only";
  output.rawUrl = textInput;

} else if (fileMatch && textInput) {
  output.inputType = "text_with_filename";
  output.rawText = textInput;

} else if (textInput) {
  output.inputType = "text_only";
  output.rawText = textInput;

} else {
  output.inputType = "unknown";
}

// --- 8️⃣ Return ---
return [
  {
    json: output,
    binary: file ? { data: file } : {},
  },
];

